use state::AppState;
use std::sync::Arc;
use tauri::{Manager, RunEvent};
use tauri_plugin_deep_link::DeepLinkExt;

fn kimo_home(app: &tauri::App) -> std::path::PathBuf {
    if let Some(h) = std::env::var_os("KIMO_HOME").filter(|h| !h.is_empty()) {
        return h.into();
    }
    app.path()
        .home_dir()
        .map(|h| h.join(".kimo"))
        .unwrap_or_else(|_| std::env::temp_dir().join("kimo"))
}

/// Builds and runs the Tauri application.
#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let _ = rustls::crypto::ring::default_provider().install_default();

    let builder = tauri::Builder::default();
    // Must be registered first: a second launch forwards its argv here and exits.
    #[cfg(any(target_os = "macos", windows, target_os = "linux"))]
    let builder = builder.plugin(tauri_plugin_single_instance::init(|app, argv, cwd| {
        let st = state::state(app);
        let args: Vec<String> = argv.into_iter().skip(1).collect();
        // `kimo-mcp --launch` while the app already runs: nothing to show.
        let background = args.iter().any(|a| a == mcp::BACKGROUND_FLAG);
        // Deep links in argv reach the deep-link plugin (single-instance "deep-link" feature).
        let reqs: Vec<_> =
            links::requests_from_args(&args, std::path::Path::new(&cwd), "second-instance")
                .into_iter()
                .filter(|r| r.source != "deep-link")
                .collect();
        if reqs.is_empty() && !background {
            if let Some(w) = window::primary_editor(app) {
                let _ = w.unminimize();
                let _ = w.set_focus();
            }
        }
        for r in reqs {
            st.open_request(app, r);
        }
    }));

    // Board 20 Qj4uq: the macOS app menu holds About / Check for updates… / Settings… ⌘,.
    #[cfg(target_os = "macos")]
    let builder = builder.menu(menu::build);
    let builder = builder.on_menu_event(|app, event| menu::on_menu_event(app, event.id().as_ref()));

    let app = builder
        .plugin(tauri_plugin_deep_link::init())
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_updater::Builder::new().build())
        .setup(|app| {
            let config_dir = app.path().app_config_dir()?;
            let data_dir = app.path().app_data_dir()?;
            let version = app.package_info().version.to_string();
            let home = kimo_home(app);
            let st = Arc::new(AppState::new(
                home.clone(),
                &config_dir,
                &data_dir,
                version.clone(),
            ));
            app.manage(st.clone());
            let handle = app.handle().clone();
            // Board 32: the macOS Dock tile animates while agents work.
            dock_activity::install(&handle);
            // Audit B12: Home re-lists watched folders when their .kimo files change on disk.
            app.manage(folder_watch::FolderWatch::default());
            folder_watch::sync(&handle, &st.recents.load().folders);

            // M6 (ADR 0014 §4, §11): keychain, AI relay, local agent CLI host.
            app.manage(Arc::new(ai::AiServices::new(
                app.path().home_dir().unwrap_or_else(|_| home.clone()),
                home.clone(),
                mcp::shim_path(),
            )));

            // M5 (ADR 0013 §7): socket/pipe + optional HTTP listeners, then the hidden
            // document host they relay to. `--background` (kimo-mcp --launch) skips the editor.
            let background = std::env::args().any(|a| a == mcp::BACKGROUND_FLAG);
            let relay = mcp::McpService::start(&handle, home, version, background);
            app.manage(relay);
            if let Err(e) = mcp::create_host_window(&handle) {
                eprintln!("kimo: {}", e.message);
            }

            // Cold-start argv (Windows/Linux file association, `kimo open`, deep links).
            let cwd = std::env::current_dir().unwrap_or_default();
            let args: Vec<String> = std::env::args().skip(1).collect();
            for r in links::requests_from_args(&args, &cwd, "argv") {
                st.open_request(&handle, r);
            }
            // macOS: files from a Finder launch that arrived before this point.
            for r in state::take_early_opens() {
                st.open_request(&handle, r);
            }

            #[cfg(any(windows, target_os = "linux"))]
            {
                let _ = app.deep_link().register_all();
            }
            let h = handle.clone();
            app.deep_link().on_open_url(move |event| {
                let st = state::state(&h);
                for url in event.urls() {
                    if let Some(l) = links::parse_deep_link(url.as_str()) {
                        st.open_request(
                            &h,
                            links::OpenRequest {
                                source: "deep-link",
                                refs: vec![l.path],
                                node: l.node,
                                page: l.page,
                            },
                        );
                    }
                }
            });

            if !background {
                window::create_editor_window(&handle, "main").map_err(|e| e.to_string())?;
            }
            Ok(())
        })
        .on_window_event(window::on_window_event)
        .invoke_handler(tauri::generate_handler![
            commands::kimo_app_info,
            commands::kimo_fs_read_text,
            commands::kimo_fs_read_bytes,
            commands::kimo_fs_write_text_atomic,
            commands::kimo_fs_write_bytes_atomic,
            commands::kimo_fs_remove,
            commands::kimo_fs_rename,
            commands::kimo_fs_copy,
            commands::kimo_fs_stat,
            commands::kimo_fs_list,
            commands::kimo_fs_watch,
            commands::kimo_fs_unwatch,
            commands::kimo_fs_reveal,
            commands::kimo_fs_open_default,
            commands::kimo_fs_open_as_text,
            commands::kimo_open_url,
            commands::kimo_dialog_open_file,
            commands::kimo_dialog_save_file,
            commands::kimo_dialog_pick_folder,
            commands::kimo_recents_list_files,
            commands::kimo_recents_note_opened,
            commands::kimo_recents_remove_file,
            commands::kimo_recents_clear,
            commands::kimo_recents_list_folders,
            commands::kimo_recents_add_folder,
            commands::kimo_recents_remove_folder,
            commands::kimo_recents_scan_folder,
            commands::kimo_trash_move,
            commands::kimo_trash_list,
            commands::kimo_trash_restore,
            commands::kimo_trash_remove,
            commands::kimo_trash_empty,
            commands::kimo_lease_acquire,
            commands::kimo_lease_release,
            commands::kimo_lease_inspect,
            commands::kimo_lease_watch,
            commands::kimo_lease_unwatch,
            commands::kimo_recovery_dir,
            commands::kimo_recovery_list,
            commands::kimo_recovery_write,
            commands::kimo_recovery_read,
            commands::kimo_recovery_discard,
            commands::kimo_recovery_prune,
            commands::kimo_git_state,
            commands::kimo_git_watch,
            commands::kimo_git_unwatch,
            commands::kimo_git_merge_driver_status,
            commands::kimo_git_install_merge_driver,
            commands::kimo_fonts_list_local,
            commands::kimo_fonts_load_local,
            commands::kimo_fonts_cache_get,
            commands::kimo_fonts_cache_put,
            commands::kimo_fonts_cache_list,
            commands::kimo_fonts_cache_stats,
            commands::kimo_fonts_cache_clear,
            commands::kimo_fonts_pack_get,
            commands::kimo_fonts_pack_put,
            commands::kimo_fonts_pack_list,
            commands::kimo_fonts_pack_stats,
            commands::kimo_fonts_pack_clear,
            commands::kimo_fonts_fetch_remote,
            commands::kimo_fonts_open_cache_folder,
            commands::kimo_help_show_logs,
            commands::kimo_menu_set_context,
            commands::kimo_clipboard_write_text,
            default_app::kimo_default_app_status,
            default_app::kimo_default_app_set,
            commands::kimo_updater_status,
            commands::kimo_updater_check,
            commands::kimo_updater_download,
            commands::kimo_updater_restart,
            commands::kimo_window_state,
            commands::kimo_window_titlebar_double_click,
            commands::kimo_window_set_title,
            commands::kimo_window_set_document_edited,
            commands::kimo_window_open_settings,
            commands::kimo_window_confirm_close,
            commands::kimo_window_close,
            commands::kimo_window_new,
            commands::kimo_settings_get_all,
            commands::kimo_settings_set,
            commands::kimo_launch_take_initial,
            commands::kimo_dock_agent_activity,
            mcp_commands::kimo_mcp_status,
            mcp_commands::kimo_mcp_connections,
            mcp_commands::kimo_mcp_disconnect,
            mcp_commands::kimo_mcp_send,
            mcp_commands::kimo_mcp_http_respond,
            mcp_commands::kimo_mcp_host_ready,
            mcp_commands::kimo_mcp_http_set_enabled,
            mcp_commands::kimo_mcp_http_token_rotate,
            mcp_commands::kimo_mcp_config_read,
            mcp_commands::kimo_mcp_config_write,
            mcp_commands::kimo_mcp_activity_append,
            mcp_commands::kimo_mcp_activity_read,
            mcp_commands::kimo_mcp_policies_get,
            mcp_commands::kimo_mcp_policies_set,
            mcp_commands::kimo_mcp_server_start,
            mcp_commands::kimo_mcp_server_stop,
            mcp_commands::kimo_mcp_server_restart,
            mcp_commands::kimo_mcp_server_settings_get,
            mcp_commands::kimo_mcp_server_settings_set,
            mcp_commands::kimo_mcp_port_check,
            mcp_commands::kimo_mcp_http_token_get,
            mcp_commands::kimo_mcp_log_info,
            mcp_commands::kimo_mcp_log_reveal,
            mcp_commands::kimo_mcp_scope_allow,
            ai_commands::kimo_secret_has,
            ai_commands::kimo_secret_set,
            ai_commands::kimo_secret_delete,
            ai_commands::kimo_secret_list,
            ai_commands::kimo_secret_hint,
            ai_commands::kimo_ai_request,
            ai_commands::kimo_ai_abort,
            ai_commands::kimo_cli_which,
            ai_commands::kimo_cli_exec,
            ai_commands::kimo_cli_home_file_exists,
            ai_commands::kimo_cli_has_env,
            ai_commands::kimo_cli_prepare_workspace,
            ai_commands::kimo_cli_spawn,
            ai_commands::kimo_cli_write,
            ai_commands::kimo_cli_close_stdin,
            ai_commands::kimo_cli_kill,
            ai_commands::kimo_skills_root,
            ai_commands::kimo_skills_list,
            ai_commands::kimo_skills_read,
            ai_commands::kimo_skills_watch,
            ai_commands::kimo_skills_unwatch,
            ai_commands::kimo_skills_reveal,
        ])
        .build(tauri::generate_context!())
        .expect("error while building the Kimo desktop app");

    app.run(|app, event| match event {
        #[cfg(target_os = "macos")]
        RunEvent::Opened { urls } => {
            // Finder double-click / "Open With" (file association). `kimo://` URLs are handled
            // by the deep-link plugin.
            let refs: Vec<String> = urls
                .iter()
                .filter(|u| u.scheme() == "file")
                .filter_map(|u| u.to_file_path().ok())
                .filter(|p| util::is_openable_path(p))
                .map(|p| util::path_str(&p))
                .collect();
            if !refs.is_empty() {
                state::open_or_defer(
                    app,
                    links::OpenRequest {
                        source: "file-association",
                        refs,
                        node: None,
                        page: None,
                    },
                );
            }
        }
        #[cfg(target_os = "macos")]
        RunEvent::Reopen {
            has_visible_windows,
            ..
        } => {
            if !has_visible_windows && window::primary_editor(app).is_none() {
                let _ = window::create_editor_window(app, "main");
            }
        }
        RunEvent::ExitRequested { api, code, .. } => {
            // Quit asks every editor window first (flush-before-close); the app exits when the
            // last one is gone. `app.exit(code)` / restart pass through.
            if code.is_none() {
                if let Some(m) = mcp::service(app) {
                    m.quitting.store(true, std::sync::atomic::Ordering::SeqCst);
                }
                if window::request_quit(app) {
                    api.prevent_exit();
                }
            }
        }
        RunEvent::Exit => {
            if let Some(a) = ai::services(app) {
                a.shutdown();
            }
            if let Some(m) = mcp::service(app) {
                m.shutdown_blocking();
            }
            state::state(app).leases.release_all_own();
        }
        _ => {}
    });
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    fn ts_commands() -> Vec<String> {
        let ts = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../../packages/platform/src/tauri.ts"
        ))
        .unwrap();
        let block = ts
            .split("export const TAURI_COMMANDS = [")
            .nth(1)
            .unwrap()
            .split(']')
            .next()
            .unwrap();
        block
            .lines()
            .filter_map(|l| {
                l.trim()
                    .strip_prefix('"')?
                    .split('"')
                    .next()
                    .map(String::from)
            })
            .collect()
    }

    /// ADR 0012: "a test asserts that the TS list is complete, and the Rust side should add a
    /// matching test when it lands".
    #[test]
    fn command_surface_matches_tauri_ts() {
        let ts = ts_commands();
        assert_eq!(ts.len(), 83);
        let rust: Vec<String> = super::command_list::COMMANDS
            .iter()
            .map(|s| s.to_string())
            .collect();
        assert_eq!(rust, ts, "command_list.rs must mirror TAURI_COMMANDS");

        let lib =
            std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/lib.rs")).unwrap();
        let handler = lib
            .split("generate_handler![")
            .nth(1)
            .unwrap()
            .split("])")
            .next()
            .unwrap();
        let registered: BTreeSet<String> = handler
            .lines()
            .filter_map(|l| {
                // The TAURI_COMMANDS surface: `commands::x` plus `default_app::x` (the agent and
                // relay modules have their own lists).
                let path = l.trim().strip_suffix(',')?;
                path.strip_prefix("commands::")
                    .or_else(|| path.strip_prefix("default_app::"))
                    .map(String::from)
            })
            .collect();
        assert_eq!(registered, ts.iter().cloned().collect::<BTreeSet<_>>());

        let cap: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/capabilities/default.json"
            ))
            .unwrap(),
        )
        .unwrap();
        let perms: BTreeSet<String> = cap["permissions"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|p| p.as_str().map(String::from))
            .collect();
        for c in &ts {
            assert!(
                perms.contains(&format!("allow-{}", c.replace('_', "-"))),
                "capability misses {c}"
            );
        }
        let extra: Vec<_> = perms
            .iter()
            .filter(|p| {
                !p.starts_with("allow-kimo-")
                    && ![
                        "core:event:allow-listen",
                        "core:event:allow-unlisten",
                        // Drag regions on the overlay title bar; Windows / Linux maximize
                        // through the internal toggle, macOS through the double-click command.
                        "core:window:allow-start-dragging",
                        "core:window:allow-internal-toggle-maximize",
                    ]
                    .contains(&p.as_str())
            })
            .collect();
        assert!(extra.is_empty(), "unexpected permissions: {extra:?}");
    }

    fn capability(name: &str) -> (BTreeSet<String>, BTreeSet<String>) {
        let cap: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(format!(
                "{}/capabilities/{name}.json",
                env!("CARGO_MANIFEST_DIR")
            ))
            .unwrap(),
        )
        .unwrap();
        let set = |k: &str| -> BTreeSet<String> {
            cap[k]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|p| p.as_str().map(String::from))
                .collect()
        };
        (set("windows"), set("permissions"))
    }

    /// ADR 0013 §11: "the shell adds a `command_list_mcp.rs` mirror" of `TAURI_MCP_COMMANDS`.
    #[test]
    fn mcp_command_surface_matches_platform_ts() {
        let ts = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../../packages/platform/src/mcp.ts"
        ))
        .unwrap();
        let block = ts
            .split("export const TAURI_MCP_COMMANDS = [")
            .nth(1)
            .unwrap()
            .split(']')
            .next()
            .unwrap();
        let ts_cmds: Vec<String> = block
            .lines()
            .filter_map(|l| {
                l.trim()
                    .strip_prefix('"')?
                    .split('"')
                    .next()
                    .map(String::from)
            })
            .collect();
        assert_eq!(ts_cmds.len(), 24);
        let rust: Vec<String> = super::command_list_mcp::MCP_COMMANDS
            .iter()
            .map(|s| s.to_string())
            .collect();
        assert_eq!(
            rust, ts_cmds,
            "command_list_mcp.rs must mirror TAURI_MCP_COMMANDS"
        );

        let lib =
            std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/lib.rs")).unwrap();
        let handler = lib
            .split("generate_handler![")
            .nth(1)
            .unwrap()
            .split("])")
            .next()
            .unwrap();
        let registered: BTreeSet<String> = handler
            .lines()
            .filter_map(|l| {
                l.trim()
                    .strip_prefix("mcp_commands::")?
                    .strip_suffix(',')
                    .map(String::from)
            })
            .collect();
        assert_eq!(registered, ts_cmds.iter().cloned().collect::<BTreeSet<_>>());

        let perm = |c: &str| format!("allow-{}", c.replace('_', "-"));
        let host_only: BTreeSet<String> = super::command_list_mcp::MCP_HOST_ONLY_COMMANDS
            .iter()
            .map(|c| perm(c))
            .collect();
        let (host_windows, host_perms) = capability("mcp-host");
        assert_eq!(
            host_windows,
            BTreeSet::from([super::mcp::HOST_LABEL.to_string()])
        );
        let (ui_windows, ui_perms) = capability("mcp-ui");
        assert!(!ui_windows.contains(super::mcp::HOST_LABEL));
        for c in &ts_cmds {
            assert!(host_perms.contains(&perm(c)), "mcp-host misses {c}");
            let p = perm(c);
            assert_eq!(
                ui_perms.contains(&p),
                !host_only.contains(&p),
                "mcp-ui grant for {c}"
            );
        }
        for p in host_perms.iter().chain(&ui_perms) {
            assert!(
                p.starts_with("allow-kimo-mcp-") || p.starts_with("core:event:allow-"),
                "unexpected permission {p}"
            );
        }
        // The host also needs the M4 surface (documents, leases, recovery).
        let (default_windows, _) = capability("default");
        assert!(default_windows.contains(super::mcp::HOST_LABEL));
    }

    /// The events Rust emits are the ones `TauriMcpEventMap` declares.
    #[test]
    fn mcp_event_names_match_platform_ts() {
        let ts = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../../packages/platform/src/mcp.ts"
        ))
        .unwrap();
        let map = ts
            .split("export interface TauriMcpEventMap {")
            .nth(1)
            .unwrap()
            .split("\n}")
            .next()
            .unwrap();
        use super::mcp::hub::{EV_CONNECTION, EV_HTTP_REQUEST, EV_IN, EV_STATUS};
        for ev in [EV_IN, EV_CONNECTION, EV_HTTP_REQUEST, EV_STATUS] {
            assert!(
                map.contains(&format!("\"{ev}\"")),
                "{ev} not in TauriMcpEventMap"
            );
        }
    }

    fn ts_list(file: &str, marker: &str) -> Vec<String> {
        let ts = std::fs::read_to_string(format!(
            "{}/../../../packages/platform/src/{file}",
            env!("CARGO_MANIFEST_DIR")
        ))
        .unwrap();
        let block = ts
            .split(&format!("export const {marker} = ["))
            .nth(1)
            .unwrap()
            .split(']')
            .next()
            .unwrap();
        // Every quoted string in the array literal (one per line or all on one line).
        block
            .split('"')
            .skip(1)
            .step_by(2)
            .map(String::from)
            .collect()
    }

    /// ADR 0014 §4/§11: the M6 commands mirror `TAURI_SECRETS_COMMANDS` / `TAURI_CLI_COMMANDS`,
    /// are all registered, and are granted by the ai-agent / ai-settings capabilities only.
    #[test]
    fn ai_command_surface_matches_platform_ts() {
        let secrets = ts_list("secrets.ts", "TAURI_SECRETS_COMMANDS");
        let cli = ts_list("cli-agents.ts", "TAURI_CLI_COMMANDS");
        let skills = ts_list("skills.ts", "TAURI_SKILLS_COMMANDS");
        assert_eq!((secrets.len(), cli.len(), skills.len()), (7, 9, 6));
        let own = |l: &[&str]| l.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        assert_eq!(own(super::command_list_ai::SECRETS_COMMANDS), secrets);
        assert_eq!(own(super::command_list_ai::CLI_COMMANDS), cli);
        assert_eq!(own(super::command_list_ai::SKILLS_COMMANDS), skills);
        let all: BTreeSet<String> = secrets.iter().chain(&cli).chain(&skills).cloned().collect();

        let lib =
            std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/lib.rs")).unwrap();
        let handler = lib
            .split("generate_handler![")
            .nth(1)
            .unwrap()
            .split("])")
            .next()
            .unwrap();
        let registered: BTreeSet<String> = handler
            .lines()
            .filter_map(|l| {
                l.trim()
                    .strip_prefix("ai_commands::")?
                    .strip_suffix(',')
                    .map(String::from)
            })
            .collect();
        assert_eq!(registered, all);

        let perm = |c: &str| format!("allow-{}", c.replace('_', "-"));
        let (agent_windows, agent_perms) = capability("ai-agent");
        assert!(agent_windows.contains("main") && agent_windows.contains("document-host"));
        assert!(!agent_windows.contains("settings"));
        let (settings_windows, settings_perms) = capability("ai-settings");
        assert_eq!(settings_windows, BTreeSet::from(["settings".to_string()]));
        let excluded: BTreeSet<String> = super::command_list_ai::AI_SETTINGS_EXCLUDED
            .iter()
            .map(|c| c.to_string())
            .collect();
        for c in &all {
            assert!(agent_perms.contains(&perm(c)), "ai-agent misses {c}");
            assert_eq!(
                settings_perms.contains(&perm(c)),
                !excluded.contains(c),
                "ai-settings grant for {c}"
            );
        }
        let expected: BTreeSet<String> = all.iter().map(|c| perm(c)).collect();
        for p in agent_perms.iter().chain(&settings_perms) {
            assert!(
                expected.contains(p)
                    || ["core:event:allow-listen", "core:event:allow-unlisten"]
                        .contains(&p.as_str()),
                "unexpected permission {p}"
            );
        }
        // No other capability grants an M6 command.
        for other in ["default", "mcp-host", "mcp-ui"] {
            let (_, perms) = capability(other);
            assert!(perms.is_disjoint(&expected), "{other} grants M6 commands");
        }
    }

    /// Event names and the shared constants match secrets.ts / cli-agents.ts.
    #[test]
    fn ai_events_and_constants_match_platform_ts() {
        let read = |f: &str| {
            std::fs::read_to_string(format!(
                "{}/../../../packages/platform/src/{f}",
                env!("CARGO_MANIFEST_DIR")
            ))
            .unwrap()
        };
        let secrets = read("secrets.ts");
        let cli = read("cli-agents.ts");
        assert_eq!(
            ts_list("secrets.ts", "TAURI_SECRETS_EVENTS"),
            vec![super::ai::relay::EV_AI_RESPONSE.to_string()]
        );
        assert_eq!(
            ts_list("cli-agents.ts", "TAURI_CLI_EVENTS"),
            vec![
                super::ai::cli::EV_CLI_OUTPUT.to_string(),
                super::ai::cli::EV_CLI_EXIT.to_string()
            ]
        );
        assert!(secrets.contains(&format!(
            "SECRET_SERVICE = \"{}\"",
            super::ai::secrets::SERVICE
        )));
        let allowed = ts_list("cli-agents.ts", "ALLOWED_CLI_COMMANDS");
        assert_eq!(
            allowed,
            super::ai::cli::BUILTIN_COMMANDS
                .iter()
                .map(|s| s.to_string())
                .collect::<Vec<_>>()
        );
        for f in ts_list("cli-agents.ts", "CLI_AUTH_FILES") {
            assert!(super::ai::cli::AUTH_FILES.contains(&f.as_str()), "{f}");
        }
        assert!(cli.contains(&format!(
            "CLI_WORKSPACES_DIR = \".kimo/{}\"",
            super::ai::cli::WORKSPACES_DIR
        )));
        // User skills (ADR 0014 §10): event, root and size cap match skills.ts.
        let skills = read("skills.ts");
        assert_eq!(
            ts_list("skills.ts", "TAURI_SKILLS_EVENTS"),
            vec![super::skills::EV_SKILLS_CHANGED.to_string()]
        );
        assert!(skills.contains(&format!(
            "USER_SKILLS_ROOT = \".kimo/{}\"",
            super::skills::SKILLS_DIR
        )));
        assert_eq!(super::skills::MAX_SKILL_BYTES, 256 * 1024);
        assert!(skills.contains("USER_SKILL_MAX_BYTES = 256 * 1024"));
        assert!(skills.contains("SKILL_DIR_RE = /^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$/"));
    }

    /// `SETTINGS_PANES` (window.rs) mirrors the `SettingsPane` union in platform types.ts, in
    /// the web sidebar order (apps/web/src/settings/model.ts).
    #[test]
    fn settings_panes_match_platform_ts() {
        let ts = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../../packages/platform/src/types.ts"
        ))
        .unwrap();
        let union = ts
            .split("export type SettingsPane =")
            .nth(1)
            .unwrap()
            .split("\n\n")
            .next()
            .unwrap();
        let panes: Vec<String> = union
            .lines()
            .filter_map(|l| {
                l.trim()
                    .strip_prefix("| \"")?
                    .split('"')
                    .next()
                    .map(String::from)
            })
            .collect();
        let rust: Vec<String> = super::window::SETTINGS_PANES
            .iter()
            .map(|s| s.to_string())
            .collect();
        assert_eq!(rust, panes);
        let web = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../web/src/settings/model.ts"
        ))
        .unwrap();
        let web_ids: Vec<String> = web
            .split("export const SETTINGS_PANES")
            .nth(1)
            .unwrap()
            .split("\n]")
            .next()
            .unwrap()
            .split("{ id: \"")
            .skip(1)
            .filter_map(|c| c.split('"').next().map(String::from))
            .collect();
        assert_eq!(rust, web_ids);
    }
}
